(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const wy1 = Math.cos(y*0.016-t*0.22)*16 + Math.sin(x*0.014+t*0.3)*11;
  const sx = x + wx1, sy = y + wy1;
  const wx2 = Math.sin(sx*0.025+sy*0.015+t*0.5)*6;
  const wy2 = Math.cos(sx*0.015-sy*0.025-t*0.4)*6;
  const sx2 = sx + wx2, sy2 = sy + wy2;
  const src = [
    [160+Math.sin(t*0.5)*110,80+Math.cos(t*0.35)*55,0.075,2.2],
    [320+Math.cos(t*0.45)*110,160+Math.sin(t*0.6)*55,0.09,1.8],
    [240+Math.sin(t*0.28+2)*150,120+Math.cos(t*0.42+1)*95,0.055,2.5],
    [120+Math.cos(t*0.7+1)*90,180+Math.sin(t*0.5+3)*70,0.11,1.6],
    [360+Math.sin(t*0.38+4)*100,60+Math.cos(t*0.8+2)*80,0.065,2.8],
    [240+Math.cos(t*0.32+5)*130,200+Math.sin(t*0.48)*90,0.085,2.0],
    [80+Math.sin(t*0.55+3)*70,40+Math.cos(t*0.65+1)*50,0.1,1.4],
    [400+Math.cos(t*0.4+2)*60,220+Math.sin(t*0.75+4)*40,0.12,1.3],
    [200+Math.sin(t*0.33+1)*100,200+Math.cos(t*0.58+3)*70,0.07,2.4]
  ];
  let aS=0,iS=0,a2=0,i2=0;
  for(const[sX,sY,f,sp]of src){
    const d1=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS+=Math.sin(d1*f-t*sp);iS+=Math.sin(d1*f*0.65+t*sp*0.55+1.5);
    a2+=Math.sin(d2*f*0.8-t*sp*0.7+0.8);i2+=Math.sin(d2*f*0.5+t*sp*0.4+2.8);
  }
  const n=src.length;
  const act=(aS+a2*0.5)/n/1.5, inh=(iS+i2*0.5)/n/1.5;
  const bg=(Math.sin(sx2*0.035+sy2*0.022+t*0.9)+Math.sin(sx2*0.028-sy2*0.038+t*1.2))/2
    +Math.sin((sx2+sy2)*0.11+t*2.8)*0.2+Math.sin((sx2-sy2)*0.09-t*2.2)*0.2
    +Math.sin(sx2*0.06+sy2*0.04+t*1.8)*0.1;
  const dist=Math.sqrt((sx2-cx)**2+(sy2-cy)**2);
  const ang=Math.atan2(sy2-cy,sx2-cx);
  const spiral=(Math.sin(dist*0.045-ang*4-t*1.8)+Math.sin(dist*0.035+ang*5-t*1.4))*0.35
    +Math.sin(dist*0.08-ang*2-t*3)*0.15;
  const cell=Math.tanh((Math.sin(sx2*0.14)*Math.sin(sy2*0.14)
    +Math.sin((sx2+sy2)*0.09+t)*0.5+Math.sin(sx2*0.08-sy2*0.12+t*0.7)*0.3)*1.8)*0.3;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+cell*0.5)*2.5);
  const detail=Math.sin(reaction*8+t*3)*0.08+Math.sin(reaction*12-t*2)*0.04;
  const blend=reaction*0.7+cell*0.2+detail;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,58],[12,55,95],[15,95,120],[20,150,145],[60,195,170],
    [190,195,75],[220,170,55],[215,110,65],[185,65,75],[120,35,85],[50,20,70],[6,12,58]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12+(Math.abs(reaction)-0.65)*0.3:0.95;
  const pulse=1.0+Math.sin(t*1.5)*0.03;
  const fn=lum*edge*pulse;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fn)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fn)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fn)|0
  ];
}
